/* Orchard — Shared Styles */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --black: #1d1d1f;
  --gray-bg: #f5f5f7;
  --gray-mid: #e8e8ed;
  --gray-text: #6e6e73;
  --blue: #0066cc;
  --blue-hover: #0077ed;
  --white: #ffffff;
  --font: -apple-system, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Arial, sans-serif;
  --transition: 0.3s ease;
  --radius: 18px;
  --card-radius: 18px;
}

html { scroll-behavior: smooth; }
body { font-family: var(--font); color: var(--black); background: var(--white); -webkit-font-smoothing: antialiased; }
a { color: var(--blue); text-decoration: none; }
a:hover { color: var(--blue-hover); text-decoration: underline; }
img { max-width: 100%; display: block; }

/* ── Ribbon Banner ── */
.ribbon {
  background: var(--gray-bg);
  text-align: center;
  font-size: 12px;
  color: var(--black);
  padding: 8px 16px;
  line-height: 1.4;
}
.ribbon a { color: var(--black); font-size: 12px; }
.ribbon a:hover { text-decoration: underline; color: var(--black); }

/* ── Navigation ── */
.nav {
  position: sticky; top: 0; z-index: 100;
  background: rgba(255,255,255,0.85);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,0.08);
}
.nav-inner {
  max-width: 1024px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 22px; height: 44px;
}
.nav-logo { font-size: 20px; font-weight: 600; color: var(--black); letter-spacing: -0.5px; }
.nav-logo:hover { color: var(--black); text-decoration: none; }
.nav-links { display: flex; gap: 20px; list-style: none; }
.nav-links a { font-size: 12px; color: var(--black); opacity: 0.8; white-space: nowrap; }
.nav-links a:hover { opacity: 1; text-decoration: none; color: var(--black); }
.nav-actions { display: flex; gap: 16px; }
.nav-actions a { font-size: 12px; color: var(--black); opacity: 0.8; }
.nav-actions a:hover { opacity: 1; text-decoration: none; }

/* ── Section Wrappers ── */
.section { padding: 80px 0; }
.section-sm { padding: 48px 0; }
.container { max-width: 1024px; margin: 0 auto; padding: 0 22px; }
.container-wide { max-width: 1200px; margin: 0 auto; padding: 0 22px; }

.section-header { margin-bottom: 32px; }
.section-header h2 { font-size: 32px; font-weight: 700; letter-spacing: -0.5px; line-height: 1.1; }
.section-header p { font-size: 17px; color: var(--gray-text); margin-top: 6px; }

/* ── Buttons ── */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 14px; font-weight: 400; border-radius: 980px;
  padding: 8px 18px; cursor: pointer; border: none;
  transition: background var(--transition), color var(--transition);
  font-family: var(--font); white-space: nowrap;
  text-decoration: none;
}
.btn-blue { background: var(--blue); color: #fff; }
.btn-blue:hover { background: var(--blue-hover); color: #fff; text-decoration: none; }
.btn-dark { background: var(--black); color: #fff; }
.btn-dark:hover { background: #3a3a3c; color: #fff; text-decoration: none; }
.btn-outline { background: transparent; color: var(--blue); border: 1px solid var(--blue); }
.btn-outline:hover { background: var(--blue); color: #fff; text-decoration: none; }
.btn-ghost { background: rgba(0,0,0,0.05); color: var(--black); }
.btn-ghost:hover { background: rgba(0,0,0,0.1); text-decoration: none; }
.btn-sm { font-size: 12px; padding: 6px 14px; }

/* ── Carousel ── */
.carousel-wrapper { position: relative; }
.carousel-track-outer { overflow: hidden; }
.carousel-track {
  display: flex; gap: 16px;
  transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  will-change: transform;
}
.carousel-nav {
  position: absolute; top: 50%; transform: translateY(-50%);
  display: flex; align-items: center; justify-content: space-between;
  pointer-events: none; width: 100%; padding: 0 8px;
  z-index: 10;
}
.carousel-btn {
  width: 40px; height: 40px; border-radius: 50%;
  background: rgba(255,255,255,0.92); border: none; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 2px 12px rgba(0,0,0,0.15);
  pointer-events: all;
  transition: background var(--transition), box-shadow var(--transition);
  flex-shrink: 0;
}
.carousel-btn:hover { background: #fff; box-shadow: 0 4px 20px rgba(0,0,0,0.2); }
.carousel-btn svg { width: 16px; height: 16px; color: var(--black); }
.carousel-btn:disabled { opacity: 0.3; cursor: default; }

/* ── Product Card ── */
.product-card {
  flex-shrink: 0; width: 240px; border-radius: var(--card-radius);
  background: var(--gray-bg); overflow: hidden;
  display: flex; flex-direction: column; padding: 24px;
  position: relative;
}
.product-card-img {
  width: 100%; height: 140px; display: flex; align-items: center; justify-content: center;
  margin-bottom: 16px;
}
.product-card-img svg { width: 80px; height: 80px; opacity: 0.85; }
.product-card-badge {
  position: absolute; top: 14px; left: 14px;
  background: var(--blue); color: #fff; font-size: 10px; font-weight: 600;
  padding: 2px 8px; border-radius: 980px; letter-spacing: 0.5px; text-transform: uppercase;
}
.product-card h3 { font-size: 17px; font-weight: 600; letter-spacing: -0.3px; margin-bottom: 4px; }
.product-card .tagline { font-size: 13px; color: var(--gray-text); margin-bottom: 12px; line-height: 1.4; flex-grow: 1; }
.product-card .price { font-size: 15px; font-weight: 500; color: var(--black); }
.product-card .monthly { font-size: 12px; color: var(--gray-text); margin-top: 2px; }
.product-card .card-link { font-size: 13px; color: var(--blue); margin-top: 12px; display: inline-block; }
.product-card .card-link:hover { text-decoration: underline; }

/* ── Hero Tiles (Homepage) ── */
.product-grid { display: grid; gap: 8px; grid-template-columns: 1fr 1fr; }
.hero-tile {
  border-radius: var(--card-radius); overflow: hidden;
  position: relative; min-height: 420px;
  display: flex; flex-direction: column; justify-content: flex-end;
  padding: 32px; background: var(--gray-bg);
}
.hero-tile-full { grid-column: 1 / -1; min-height: 500px; }
.hero-tile .tile-content { position: relative; z-index: 2; }
.hero-tile .tile-eyebrow { font-size: 13px; color: var(--gray-text); margin-bottom: 4px; }
.hero-tile h2 { font-size: 36px; font-weight: 700; letter-spacing: -1px; line-height: 1.1; margin-bottom: 6px; }
.hero-tile .tile-tag { font-size: 17px; color: var(--gray-text); margin-bottom: 16px; line-height: 1.4; }
.hero-tile .tile-ctabar { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.hero-tile .tile-visual {
  position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  display: flex; align-items: center; justify-content: center;
  padding-bottom: 140px;
}
.hero-tile .tile-visual svg { opacity: 0.15; }

/* Tile gradient themes */
.tile-phone { background: linear-gradient(135deg, #1c1c1e 0%, #2c2c2e 100%); }
.tile-phone h2, .tile-phone .tile-tag, .tile-phone .tile-eyebrow { color: #fff; }
.tile-phone .tile-tag { color: rgba(255,255,255,0.7); }
.tile-phone .btn-dark { background: rgba(255,255,255,0.15); }
.tile-phone .btn-dark:hover { background: rgba(255,255,255,0.25); }

.tile-laptop { background: linear-gradient(135deg, #f0f4ff 0%, #dce8ff 100%); }
.tile-laptop-pro { background: linear-gradient(135deg, #1c1c1e 0%, #2c2c2e 100%); }
.tile-laptop-pro h2, .tile-laptop-pro .tile-tag, .tile-laptop-pro .tile-eyebrow { color: #fff; }
.tile-laptop-pro .tile-tag { color: rgba(255,255,255,0.7); }

.tile-tablet { background: linear-gradient(135deg, #f5f0ff 0%, #e8dcff 100%); }
.tile-earbuds { background: linear-gradient(135deg, #fff5f0 0%, #ffe8dc 100%); }
.tile-tradein { background: linear-gradient(135deg, #f0fff5 0%, #dcffe8 100%); }

/* ── Entertainment Tabs ── */
.tab-bar { display: flex; gap: 0; border-bottom: 1px solid var(--gray-mid); margin-bottom: 32px; overflow-x: auto; }
.tab-btn {
  flex-shrink: 0; background: none; border: none; padding: 12px 24px;
  font-size: 15px; font-weight: 500; color: var(--gray-text); cursor: pointer;
  border-bottom: 2px solid transparent; font-family: var(--font);
  transition: color var(--transition), border-color var(--transition);
}
.tab-btn.active { color: var(--black); border-bottom-color: var(--black); }
.tab-btn:hover { color: var(--black); }
.tab-panel { display: none; }
.tab-panel.active { display: block; }

.ent-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
.ent-card {
  background: var(--gray-bg); border-radius: 12px; overflow: hidden;
  aspect-ratio: 3/4; display: flex; flex-direction: column; position: relative;
}
.ent-card-body { padding: 16px; margin-top: auto; }
.ent-card-body h4 { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
.ent-card-body p { font-size: 12px; color: var(--gray-text); margin-bottom: 8px; }
.ent-card-thumb { flex-grow: 1; background: var(--gray-mid); display: flex; align-items: center; justify-content: center; }

/* ── Store Hero ── */
.store-hero { padding: 60px 0 40px; text-align: center; }
.store-hero h1 { font-size: 56px; font-weight: 700; letter-spacing: -2px; line-height: 1; margin-bottom: 6px; }
.store-hero p { font-size: 21px; color: var(--gray-text); margin-bottom: 24px; }
.store-hero-links { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ── Category Icon Bar ── */
.icon-bar { border-top: 1px solid var(--gray-mid); border-bottom: 1px solid var(--gray-mid); padding: 0; background: var(--white); position: sticky; top: 44px; z-index: 90; }
.icon-bar-inner { display: flex; overflow-x: auto; scrollbar-width: none; -ms-overflow-style: none; }
.icon-bar-inner::-webkit-scrollbar { display: none; }
.icon-bar-item { flex-shrink: 0; display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 12px 20px; text-decoration: none; }
.icon-bar-item:hover { text-decoration: none; background: var(--gray-bg); }
.icon-bar-item span { font-size: 11px; color: var(--gray-text); white-space: nowrap; }
.icon-bar-item:hover span { color: var(--black); }
.icon-bar-icon { width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; }

/* ── Section Nav (category pages) ── */
.section-nav { border-bottom: 1px solid var(--gray-mid); background: var(--white); position: sticky; top: 44px; z-index: 90; }
.section-nav-inner { display: flex; overflow-x: auto; scrollbar-width: none; -ms-overflow-style: none; max-width: 1024px; margin: 0 auto; padding: 0 22px; }
.section-nav-inner::-webkit-scrollbar { display: none; }
.section-nav-link { flex-shrink: 0; padding: 12px 20px; font-size: 13px; color: var(--gray-text); text-decoration: none; border-bottom: 2px solid transparent; white-space: nowrap; }
.section-nav-link:hover { color: var(--black); text-decoration: none; }
.section-nav-link.active { color: var(--black); border-bottom-color: var(--black); }

/* ── Category Hero ── */
.category-hero { padding: 48px 0 40px; text-align: center; background: var(--white); }
.category-hero .breadcrumb { font-size: 12px; color: var(--gray-text); margin-bottom: 12px; }
.category-hero .breadcrumb a { color: var(--blue); }
.category-hero h1 { font-size: 48px; font-weight: 700; letter-spacing: -1.5px; line-height: 1.1; margin-bottom: 8px; }
.category-hero p { font-size: 19px; color: var(--gray-text); }

/* ── Help Cards ── */
.help-card { flex-shrink: 0; width: 220px; background: var(--gray-bg); border-radius: var(--card-radius); padding: 24px; display: flex; flex-direction: column; }
.help-card .help-icon { width: 40px; height: 40px; background: var(--white); border-radius: 50%; display: flex; align-items: center; justify-content: center; margin-bottom: 16px; box-shadow: 0 2px 8px rgba(0,0,0,0.08); }
.help-card h3 { font-size: 15px; font-weight: 600; margin-bottom: 6px; }
.help-card p { font-size: 13px; color: var(--gray-text); line-height: 1.5; flex-grow: 1; }

/* ── Difference Cards ── */
.diff-card { flex-shrink: 0; width: 200px; background: var(--gray-bg); border-radius: var(--card-radius); padding: 24px; display: flex; flex-direction: column; }
.diff-card h3 { font-size: 15px; font-weight: 600; margin-bottom: 6px; }
.diff-card p { font-size: 13px; color: var(--gray-text); line-height: 1.5; }

/* ── Accessory / Audio Cards ── */
.acc-card { flex-shrink: 0; width: 220px; border-radius: var(--card-radius); background: var(--gray-bg); overflow: hidden; }
.acc-card-img { height: 160px; display: flex; align-items: center; justify-content: center; background: var(--gray-mid); }
.acc-card-body { padding: 16px; }
.acc-card-body h3 { font-size: 14px; font-weight: 600; margin-bottom: 4px; line-height: 1.3; }
.acc-card-body .price { font-size: 14px; color: var(--black); }
.acc-card-body .note { font-size: 12px; color: var(--blue); margin-top: 4px; }

/* ── Savings / Offers Cards ── */
.offer-card { flex-shrink: 0; width: 280px; border-radius: var(--card-radius); background: var(--gray-bg); padding: 28px; display: flex; flex-direction: column; }
.offer-card h3 { font-size: 19px; font-weight: 600; margin-bottom: 8px; letter-spacing: -0.3px; }
.offer-card p { font-size: 14px; color: var(--gray-text); line-height: 1.5; flex-grow: 1; }
.offer-card a { font-size: 13px; color: var(--blue); margin-top: 12px; display: inline-block; }

/* ── Brand Collab ── */
.brand-collab { background: var(--black); color: #fff; padding: 80px 0; text-align: center; }
.brand-collab h2 { font-size: 40px; font-weight: 700; letter-spacing: -1px; margin-bottom: 8px; }
.brand-collab p { font-size: 19px; color: rgba(255,255,255,0.7); max-width: 480px; margin: 0 auto 24px; }

/* ── Ways to Save ── */
.save-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.save-card { background: var(--gray-bg); border-radius: var(--card-radius); padding: 28px; }
.save-card h3 { font-size: 17px; font-weight: 600; margin-bottom: 8px; }
.save-card p { font-size: 14px; color: var(--gray-text); line-height: 1.5; }
.save-card a { font-size: 13px; color: var(--blue); display: inline-block; margin-top: 8px; }

/* ── Shopping Guides ── */
.guides-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
.guide-card { background: var(--gray-bg); border-radius: var(--card-radius); padding: 24px; }
.guide-card h3 { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
.guide-card p { font-size: 13px; color: var(--gray-text); line-height: 1.5; }

/* ── Quick Links ── */
.quick-links { border-top: 1px solid var(--gray-mid); border-bottom: 1px solid var(--gray-mid); padding: 24px 0; }
.quick-links-inner { display: flex; gap: 12px; flex-wrap: wrap; justify-content: center; }
.quick-link-btn { background: var(--gray-bg); border-radius: 980px; padding: 10px 22px; font-size: 14px; color: var(--black); text-decoration: none; border: none; cursor: pointer; font-family: var(--font); }
.quick-link-btn:hover { background: var(--gray-mid); color: var(--black); text-decoration: none; }

/* ── Footer ── */
.footer { background: var(--gray-bg); border-top: 1px solid var(--gray-mid); padding: 40px 0 24px; }
.footer-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 24px; margin-bottom: 32px; }
.footer-col h4 { font-size: 12px; font-weight: 600; color: var(--black); margin-bottom: 12px; letter-spacing: 0.2px; }
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
.footer-col li a { font-size: 12px; color: var(--gray-text); }
.footer-col li a:hover { color: var(--black); text-decoration: none; }
.footer-legal { font-size: 12px; color: var(--gray-text); border-top: 1px solid var(--gray-mid); padding-top: 16px; line-height: 1.6; }
.footer-bottom { display: flex; justify-content: space-between; align-items: center; margin-top: 12px; flex-wrap: wrap; gap: 8px; }
.footer-bottom span { font-size: 12px; color: var(--gray-text); }

/* ── Promo Banner (audio) ── */
.promo-banner { background: var(--blue); color: #fff; text-align: center; padding: 12px 24px; border-radius: 12px; font-size: 14px; margin-bottom: 28px; }

/* ── Setup/Support Section ── */
.support-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.support-card { background: var(--gray-bg); border-radius: var(--card-radius); padding: 28px; }
.support-card h3 { font-size: 17px; font-weight: 600; margin-bottom: 8px; }
.support-card p { font-size: 14px; color: var(--gray-text); line-height: 1.5; }
.support-card a { font-size: 13px; color: var(--blue); display: inline-block; margin-top: 10px; }

/* ── Mobile Responsive ── */
@media (max-width: 768px) {
  .nav-links { display: none; }
  .product-grid { grid-template-columns: 1fr; }
  .hero-tile-full { min-height: 340px; }
  .hero-tile { min-height: 320px; padding: 24px; }
  .hero-tile h2 { font-size: 28px; }
  .ent-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr; }
  .save-grid { grid-template-columns: 1fr; }
  .guides-grid { grid-template-columns: 1fr; }
  .support-cards { grid-template-columns: 1fr; }
  .store-hero h1 { font-size: 36px; }
  .category-hero h1 { font-size: 32px; }

  /* Footer accordion on mobile */
  .footer-col h4 { cursor: pointer; display: flex; justify-content: space-between; align-items: center; }
  .footer-col h4::after { content: '+'; font-size: 16px; font-weight: 300; }
  .footer-col.open h4::after { content: '−'; }
  .footer-col ul { display: none; }
  .footer-col.open ul { display: flex; }
}

@media (max-width: 480px) {
  .ent-grid { grid-template-columns: 1fr 1fr; }
  .section { padding: 48px 0; }
}

/* ── Icon SVGs as inline CSS backgrounds ── */
.icon-laptop { color: var(--black); }

/* ── Utility ── */
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }
.text-blue { color: var(--blue); }
.text-gray { color: var(--gray-text); }
.mt-4 { margin-top: 16px; }
.mt-8 { margin-top: 32px; }
.flex { display: flex; }
.gap-2 { gap: 8px; }
.items-center { align-items: center; }

/* Orchard — Shared Styles */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --black: #1d1d1f;
  --gray-bg: #f5f5f7;
  --gray-mid: #e8e8ed;
  --gray-text: #6e6e73;
  --blue: #0066cc;
  --blue-hover: #0077ed;
  --white: #ffffff;
  --font: -apple-system, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Arial, sans-serif;
  --transition: 0.3s ease;
  --radius: 18px;
  --card-radius: 18px;
}

html { scroll-behavior: smooth; }
body { font-family: var(--font); color: var(--black); background: var(--white); -webkit-font-smoothing: antialiased; }
a { color: var(--blue); text-decoration: none; }
a:hover { color: var(--blue-hover); text-decoration: underline; }
img { max-width: 100%; display: block; }

/* ── Ribbon Banner ── */
.ribbon {
  background: var(--gray-bg);
  text-align: center;
  font-size: 12px;
  color: var(--black);
  padding: 8px 16px;
  line-height: 1.4;
}
.ribbon a { color: var(--black); font-size: 12px; }
.ribbon a:hover { text-decoration: underline; color: var(--black); }

/* ── Navigation ── */
.nav {
  position: sticky; top: 0; z-index: 100;
  background: rgba(255,255,255,0.85);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,0.08);
}
.nav-inner {
  max-width: 1024px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 22px; height: 44px;
}
.nav-logo { font-size: 20px; font-weight: 600; color: var(--black); letter-spacing: -0.5px; }
.nav-logo:hover { color: var(--black); text-decoration: none; }
.nav-links { display: flex; gap: 20px; list-style: none; }
.nav-links a { font-size: 12px; color: var(--black); opacity: 0.8; white-space: nowrap; }
.nav-links a:hover { opacity: 1; text-decoration: none; color: var(--black); }
.nav-actions { display: flex; gap: 16px; }
.nav-actions a { font-size: 12px; color: var(--black); opacity: 0.8; }
.nav-actions a:hover { opacity: 1; text-decoration: none; }

/* ── Section Wrappers ── */
.section { padding: 80px 0; }
.section-sm { padding: 48px 0; }
.container { max-width: 1024px; margin: 0 auto; padding: 0 22px; }
.container-wide { max-width: 1200px; margin: 0 auto; padding: 0 22px; }

.section-header { margin-bottom: 32px; }
.section-header h2 { font-size: 32px; font-weight: 700; letter-spacing: -0.5px; line-height: 1.1; }
.section-header p { font-size: 17px; color: var(--gray-text); margin-top: 6px; }

/* ── Buttons ── */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 14px; font-weight: 400; border-radius: 980px;
  padding: 8px 18px; cursor: pointer; border: none;
  transition: background var(--transition), color var(--transition);
  font-family: var(--font); white-space: nowrap;
  text-decoration: none;
}
.btn-blue { background: var(--blue); color: #fff; }
.btn-blue:hover { background: var(--blue-hover); color: #fff; text-decoration: none; }
.btn-dark { background: var(--black); color: #fff; }
.btn-dark:hover { background: #3a3a3c; color: #fff; text-decoration: none; }
.btn-outline { background: transparent; color: var(--blue); border: 1px solid var(--blue); }
.btn-outline:hover { background: var(--blue); color: #fff; text-decoration: none; }
.btn-ghost { background: rgba(0,0,0,0.05); color: var(--black); }
.btn-ghost:hover { background: rgba(0,0,0,0.1); text-decoration: none; }
.btn-sm { font-size: 12px; padding: 6px 14px; }

/* ── Carousel ── */
.carousel-wrapper { position: relative; }
.carousel-track-outer { overflow: hidden; }
.carousel-track {
  display: flex; gap: 16px;
  transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  will-change: transform;
}
.carousel-nav {
  position: absolute; top: 50%; transform: translateY(-50%);
  display: flex; align-items: center; justify-content: space-between;
  pointer-events: none; width: 100%; padding: 0 8px;
  z-index: 10;
}
.carousel-btn {
  width: 40px; height: 40px; border-radius: 50%;
  background: rgba(255,255,255,0.92); border: none; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 2px 12px rgba(0,0,0,0.15);
  pointer-events: all;
  transition: background var(--transition), box-shadow var(--transition);
  flex-shrink: 0;
}
.carousel-btn:hover { background: #fff; box-shadow: 0 4px 20px rgba(0,0,0,0.2); }
.carousel-btn svg { width: 16px; height: 16px; color: var(--black); }
.carousel-btn:disabled { opacity: 0.3; cursor: default; }

/* ── Product Card ── */
.product-card {
  flex-shrink: 0; width: 240px; border-radius: var(--card-radius);
  background: var(--gray-bg); overflow: hidden;
  display: flex; flex-direction: column; padding: 24px;
  position: relative;
}
.product-card-img {
  width: 100%; height: 140px; display: flex; align-items: center; justify-content: center;
  margin-bottom: 16px;
}
.product-card-img svg { width: 80px; height: 80px; opacity: 0.85; }
.product-card-badge {
  position: absolute; top: 14px; left: 14px;
