/* ── Difference Cards ── */
.diff-card { flex-shrink: 0; width: 200px; background: var(--gray-bg); border-radius: var(--card-radius); padding: 24px; display: flex; flex-direction: column; }
.diff-card h3 { font-size: 15px; font-weight: 600; margin-bottom: 6px; }
.diff-card p { font-size: 13px; color: var(--gray-text); line-height: 1.5; }

/* ── Accessory / Audio Cards ── */
.acc-card { flex-shrink: 0; width: 220px; border-radius: var(--card-radius); background: var(--gray-bg); overflow: hidden; }
.acc-card-img { height: 160px; display: flex; align-items: center; justify-content: center; background: var(--gray-mid); }
.acc-card-body { padding: 16px; }
.acc-card-body h3 { font-size: 14px; font-weight: 600; margin-bottom: 4px; line-height: 1.3; }
.acc-card-body .price { font-size: 14px; color: var(--black); }
.acc-card-body .note { font-size: 12px; color: var(--blue); margin-top: 4px; }

/* ── Savings / Offers Cards ── */
.offer-card { flex-shrink: 0; width: 280px; border-radius: var(--card-radius); background: var(--gray-bg); padding: 28px; display: flex; flex-direction: column; }
.offer-card h3 { font-size: 19px; font-weight: 600; margin-bottom: 8px; letter-spacing: -0.3px; }
.offer-card p { font-size: 14px; color: var(--gray-text); line-height: 1.5; flex-grow: 1; }
.offer-card a { font-size: 13px; color: var(--blue); margin-top: 12px; display: inline-block; }

/* ── Brand Collab ── */
.brand-collab { background: var(--black); color: #fff; padding: 80px 0; text-align: center; }
.brand-collab h2 { font-size: 40px; font-weight: 700; letter-spacing: -1px; margin-bottom: 8px; }
.brand-collab p { font-size: 19px; color: rgba(255,255,255,0.7); max-width: 480px; margin: 0 auto 24px; }

/* ── Ways to Save ── */
.save-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.save-card { background: var(--gray-bg); border-radius: var(--card-radius); padding: 28px; }
.save-card h3 { font-size: 17px; font-weight: 600; margin-bottom: 8px; }
.save-card p { font-size: 14px; color: var(--gray-text); line-height: 1.5; }
.save-card a { font-size: 13px; color: var(--blue); display: inline-block; margin-top: 8px; }

/* ── Shopping Guides ── */
.guides-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
.guide-card { background: var(--gray-bg); border-radius: var(--card-radius); padding: 24px; }
.guide-card h3 { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
.guide-card p { font-size: 13px; color: var(--gray-text); line-height: 1.5; }

/* ── Quick Links ── */
.quick-links { border-top: 1px solid var(--gray-mid); border-bottom: 1px solid var(--gray-mid); padding: 24px 0; }
.quick-links-inner { display: flex; gap: 12px; flex-wrap: wrap; justify-content: center; }
.quick-link-btn { background: var(--gray-bg); border-radius: 980px; padding: 10px 22px; font-size: 14px; color: var(--black); text-decoration: none; border: none; cursor: pointer; font-family: var(--font); }
.quick-link-btn:hover { background: var(--gray-mid); color: var(--black); text-decoration: none; }

/* ── Footer ── */
.footer { background: var(--gray-bg); border-top: 1px solid var(--gray-mid); padding: 40px 0 24px; }
.footer-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 24px; margin-bottom: 32px; }
.footer-col h4 { font-size: 12px; font-weight: 600; color: var(--black); margin-bottom: 12px; letter-spacing: 0.2px; }
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
.footer-col li a { font-size: 12px; color: var(--gray-text); }
.footer-col li a:hover { color: var(--black); text-decoration: none; }
.footer-legal { font-size: 12px; color: var(--gray-text); border-top: 1px solid var(--gray-mid); padding-top: 16px; line-height: 1.6; }
.footer-bottom { display: flex; justify-content: space-between; align-items: center; margin-top: 12px; flex-wrap: wrap; gap: 8px; }
.footer-bottom span { font-size: 12px; color: var(--gray-text); }

/* ── Promo Banner (audio) ── */
.promo-banner { background: var(--blue); color: #fff; text-align: center; padding: 12px 24px; border-radius: 12px; font-size: 14px; margin-bottom: 28px; }

/* ── Setup/Support Section ── */
.support-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.support-card { background: var(--gray-bg); border-radius: var(--card-radius); padding: 28px; }
.support-card h3 { font-size: 17px; font-weight: 600; margin-bottom: 8px; }
.support-card p { font-size: 14px; color: var(--gray-text); line-height: 1.5; }
.support-card a { font-size: 13px; color: var(--blue); display: inline-block; margin-top: 10px; }

/* ── Mobile Responsive ── */
@media (max-width: 768px) {
  .nav-links { display: none; }
  .product-grid { grid-template-columns: 1fr; }
  .hero-tile-full { min-height: 340px; }
  .hero-tile { min-height: 320px; padding: 24px; }
  .hero-tile h2 { font-size: 28px; }
  .ent-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr; }
  .save-grid { grid-template-columns: 1fr; }
  .guides-grid { grid-template-columns: 1fr; }
  .support-cards { grid-template-columns: 1fr; }
  .store-hero h1 { font-size: 36px; }
  .category-hero h1 { font-size: 32px; }

  /* Footer accordion on mobile */
  .footer-col h4 { cursor: pointer; display: flex; justify-content: space-between; align-items: center; }
  .footer-col h4::after { content: '+'; font-size: 16px; font-weight: 300; }
  .footer-col.open h4::after { content: '−'; }
  .footer-col ul { display: none; }
  .footer-col.open ul { display: flex; }
}

@media (max-width: 480px) {
  .ent-grid { grid-template-columns: 1fr 1fr; }
  .section { padding: 48px 0; }
